     AND ali.PROCESS_INSTANCE_KEY = #{query.processInstanceKey, jdbcType=INTEGER}


     AND ali.ELEMENT_INSTANCE_KEY = #{query.elementInstanceKey, jdbcType=INTEGER}


     AND ali.DUE_DATE = #{query.dueDate, jdbcType=TIMESTAMP}


